/* Lexer token types */
typedef enum {
    /* Literals & identifiers */
    TOK_INT, TOK_FLOAT, TOK_STRING, TOK_IDENT,

    /* Keywords */
    TOK_FN, TOK_RETURN, TOK_IF, TOK_ELSE, TOK_WHILE, TOK_FOR, TOK_IN, TOK_LET, TOK_VAR, TOK_EXTERN,

    /* Operators */
    TOK_PLUS, TOK_MINUS, TOK_STAR, TOK_SLASH, TOK_PERCENT,
    TOK_EQ, TOK_NE, TOK_LT, TOK_LE, TOK_GT, TOK_GE,
    TOK_ASSIGN, TOK_LPAREN, TOK_RPAREN, TOK_LBRACE, TOK_RBRACE, TOK_LBRACKET, TOK_RBRACKET,
    TOK_COMMA, TOK_DOT, TOK_COLON, TOK_SEMICOLON, TOK_ARROW, TOK_AND, TOK_OR, TOK_NOT,

    /* Special */
    TOK_EOF, TOK_ERROR
} TokenKind;

typedef struct {
    TokenKind kind;
    const char *text;
    int length;
    long long int_value;
    double float_value;
    int line, col;
} Token;

typedef struct {
    const char *input;
    int pos;
    int line, col;
