/* Result enum-like structure */
struct Result {
    is_ok: i64,      /* 1 = ok, 0 = error */
    value: i64,      /* success value */
    error: i64,      /* error code */
}

fn safe_divide(a: i64, b: i64) -> Result {
    var result: Result;
    if (b == 0) {
        result.is_ok = 0;
        result.error = 1;  /* DivideByZero */
    } else {
        result.is_ok = 1;
        result.value = a / b;
        result.error = 0;
    }
    return result;
}

fn main() -> i64 {
    var res: Result = safe_divide(10, 2);
    if (res.is_ok == 1) {
        return res.value;  /* 5 */
    }
    return res.error;
}

